import app from 'flarum/forum/app';
import Button from 'flarum/common/components/Button';
import SplitDropdown from 'flarum/common/components/SplitDropdown';
import Icon from 'flarum/common/components/Icon';
import Tooltip from 'flarum/common/components/Tooltip';
import { bytes, number } from '../../depot-api';
import { t } from '../bits';
import { dotted, watchButton, when } from './shared';

/**
 * A paid file for someone who hasn't bought it: Kiosk's own offer, so every
 * Buy button on the forum is the same.
 */
export function offer(file) {
  // Kiosk's component, typed only on Kiosk's side.
  let LockedNotice = null;
  try {
    const mod = flarum.reg.get('ernestdefoe-kiosk', 'forum/components/LockedNotice');
    LockedNotice = mod && (mod.default || mod);
  } catch (e) {
    // Kiosk is absent or its registry lookup failed: the notice shows without a Buy button.
    LockedNotice = null;
  }
  return m("div", {
    className: "DepotOffer"
  }, m("p", {
    className: "Depot-dim"
  }, m(Icon, {
    name: "fas fa-lock"
  }), " ", t('file.paid_notice')), !app.session.user ? m(Button, {
    className: "Button Button--primary Button--large",
    onclick: () => app.modal.show(() => flarum.reg.asyncModuleImport('flarum/forum/components/LogInModal'))
  }, t('file.login_to_buy')) : LockedNotice ? m(LockedNotice, {
    type: 'depot-file',
    id: file.id,
    title: t('file.buy_title')
  }) : null);
}

/** The download button with older versions in its menu, or why there is none. */
function downloadButton(page, file, v) {
  if (file.canDownload) {
    return m(SplitDropdown, {
      className: "DepotDownloadSplit",
      buttonClassName: "Button Button--primary Button--large",
      icon: "fas fa-download",
      accessibleToggleLabel: t('file.older_versions')
    }, m(Button, {
      icon: "fas fa-download",
      onclick: () => page.download(file, v)
    }, t('file.download', {
      version: v.version
    })), file.versions.slice(1, 8).map(old => m(Button, {
      icon: "fas fa-history",
      onclick: () => page.download(file, old)
    }, t('file.download_old', {
      version: old.version,
      time: when(old.date)
    }))));
  }
  return file.paid ? page.offer(file) : m(Button, {
    className: "Button Button--large",
    disabled: true
  }, app.session.user ? t('file.no_download_permission') : t('file.login_to_download'));
}

/** An uploaded or linked file: the download button, its older versions, and Watch. */
export function downloadCard(page, file, v) {
  return m("div", {
    className: "DepotSideCard DepotSideCard--download"
  }, downloadButton(page, file, v), m("div", {
    className: "DepotSideCard-sub"
  }, dotted([v.external ? v.host : v.filename && v.filename.includes('.') ? v.filename.split('.').pop().toUpperCase() : null, v.size ? bytes(v.size) : null, t('file.released', {
    time: when(v.date)
  })])), watchButton(page, file), m("div", {
    className: "DepotSideCard-trust"
  }, v.sha256 ? m(Tooltip, {
    text: t('file.verified_tooltip')
  }, m("span", null, m(Icon, {
    name: "fas fa-shield-alt"
  }), " ", t('file.verified'))) : m("span", null), m("span", null, m(Icon, {
    name: "far fa-eye"
  }), " ", t('file.watchers', {
    count: number(file.watchers)
  }))));
}
flarum.reg.add('ernestdefoe-depot', 'forum/components/file/DownloadCard', { offer: offer,downloadCard: downloadCard, });