import app from 'flarum/forum/app';
import Icon from 'flarum/common/components/Icon';
import { t } from '../bits';

/*
 * The upload form's support-discussion step: which tag it goes in, and a
 * preview of how it will look.
 */

/** The flarum/tags model methods read here; flarum/tags ships no typings for core to see. */

/** The forum's primary tags the member may start a discussion in, from the boot payload. */
export function supportTags() {
  return (app.store.all('tags') || []).filter(tag => tag.isPrimary() && !tag.parent() && tag.canStartDiscussion()).map(tag => ({
    id: tag.id(),
    name: tag.name(),
    color: tag.color() || 'var(--control-color)',
    icon: tag.icon(),
    description: tag.description()
  }));
}

/** One button per tag the support discussion can go in. */
export function tagPicker(th, tags) {
  return m("div", {
    className: "DepotTagPick",
    role: "radiogroup"
  }, tags.map(tag => m("button", {
    type: "button",
    role: "radio",
    "aria-checked": th.tag === tag.id ? 'true' : 'false',
    className: th.tag === tag.id ? 'is-active' : '',
    style: {
      '--label-color': tag.color
    },
    onclick: () => th.tag = tag.id
  }, m("span", {
    className: "DepotTagPick-icon"
  }, tag.icon ? m(Icon, {
    name: tag.icon
  }) : null), m("span", null, m("b", null, tag.name), tag.description ? m("span", {
    className: "Depot-dim"
  }, tag.description) : null))));
}

/** How the support discussion will look in the discussion list. */
export function threadPreview(fileTitle, chosen) {
  const user = app.session.user;
  return m("div", {
    className: "DepotThreadPreview"
  }, m("span", {
    className: "Depot-dim"
  }, t('upload.thread_preview')), m("div", {
    className: "DepotThreadPreview-item"
  }, m("span", {
    className: "Avatar Avatar--mini",
    style: {
      '--avatar-bg': user ? user.color() : 'var(--control-bg)'
    }
  }, user ? user.displayName().charAt(0).toUpperCase() : '?'), m("div", null, m("b", null, t('upload.thread_title', {
    title: fileTitle || '…'
  })), m("div", {
    className: "DepotThreadPreview-meta"
  }, chosen ? m("span", {
    className: "Depot-label",
    style: {
      '--label-color': chosen.color
    }
  }, chosen.name) : null, m("span", {
    className: "Depot-badge"
  }, m(Icon, {
    name: "fas fa-box-open"
  }), " ", t('upload.thread_linked'))))));
}
flarum.reg.add('ernestdefoe-depot', 'forum/components/form/supportThread', { supportTags: supportTags,tagPicker: tagPicker,threadPreview: threadPreview, });